#include <Arduino.h>
const int RGB1_R = 2;
const int RGB1_G = 3;
const int RGB1_B = 4;
const int RGB2_R = 5;
const int RGB2_G = 6;
const int RGB2_B = 7;
const int RGB3_R = 8;
const int RGB3_G = 9;
const int RGB3_B = 10;
const int SHCP_PIN = A2;
const int STCP_PIN = A1;
const int DS_PIN = A0;
const byte segmentCodes[] = {
  0b11000000, 
  0b11111001, 
  0b10100100, 
  0b10110000, 
  0b10011001, 
  0b10010010, 
  0b10000010, 
  0b11111000, 
  0b10000000, 
  0b10010000  
};
int countdown = 99;
int colorIndex = 0;
unsigned long lastUpdate = 0;

void setup();
void loop();
void updateRGBLEDs();
void displayNumber(int number);
void setup() {
  pinMode(RGB1_R, OUTPUT);
  pinMode(RGB1_G, OUTPUT);
  pinMode(RGB1_B, OUTPUT);
  pinMode(RGB2_R, OUTPUT);
  pinMode(RGB2_G, OUTPUT);
  pinMode(RGB2_B, OUTPUT);
  pinMode(RGB3_R, OUTPUT);
  pinMode(RGB3_G, OUTPUT);
  pinMode(RGB3_B, OUTPUT);
  pinMode(SHCP_PIN, OUTPUT);
  pinMode(STCP_PIN, OUTPUT);
  pinMode(DS_PIN, OUTPUT);
  digitalWrite(RGB1_R, HIGH);
  digitalWrite(RGB1_G, LOW);
  digitalWrite(RGB1_B, LOW);
  displayNumber(countdown);
}
void loop() {
  if (millis() - lastUpdate >= 2000) {
    lastUpdate = millis();
    countdown--;
    if (countdown < 0) {
      countdown = 99;
      colorIndex = 0;
    }
    updateRGBLEDs();
    displayNumber(countdown);
  }
}
void updateRGBLEDs() {
  colorIndex = (colorIndex + 1) % 6;
  switch (colorIndex) {
    case 0: 
      digitalWrite(RGB1_R, HIGH); digitalWrite(RGB1_G, LOW); digitalWrite(RGB1_B, LOW);
      digitalWrite(RGB2_R, LOW); digitalWrite(RGB2_G, LOW); digitalWrite(RGB2_B, LOW);
      digitalWrite(RGB3_R, LOW); digitalWrite(RGB3_G, LOW); digitalWrite(RGB3_B, LOW);
      break;
    case 1: 
      digitalWrite(RGB1_R, LOW); digitalWrite(RGB1_G, LOW); digitalWrite(RGB1_B, LOW);
      digitalWrite(RGB2_R, LOW); digitalWrite(RGB2_G, HIGH); digitalWrite(RGB2_B, LOW);
      digitalWrite(RGB3_R, LOW); digitalWrite(RGB3_G, LOW); digitalWrite(RGB3_B, LOW);
      break;
    case 2: 
      digitalWrite(RGB1_R, LOW); digitalWrite(RGB1_G, LOW); digitalWrite(RGB1_B, LOW);
      digitalWrite(RGB2_R, LOW); digitalWrite(RGB2_G, LOW); digitalWrite(RGB2_B, LOW);
      digitalWrite(RGB3_R, LOW); digitalWrite(RGB3_G, LOW); digitalWrite(RGB3_B, HIGH);
      break;
    case 3: 
      digitalWrite(RGB1_R, HIGH); digitalWrite(RGB1_G, LOW); digitalWrite(RGB1_B, HIGH);
      digitalWrite(RGB2_R, LOW); digitalWrite(RGB2_G, LOW); digitalWrite(RGB2_B, LOW);
      digitalWrite(RGB3_R, LOW); digitalWrite(RGB3_G, LOW); digitalWrite(RGB3_B, LOW);
      break;
    case 4: 
      digitalWrite(RGB1_R, LOW); digitalWrite(RGB1_G, LOW); digitalWrite(RGB1_B, LOW);
      digitalWrite(RGB2_R, HIGH); digitalWrite(RGB2_G, HIGH); digitalWrite(RGB2_B, LOW);
      digitalWrite(RGB3_R, LOW); digitalWrite(RGB3_G, LOW); digitalWrite(RGB3_B, LOW);
      break;
    case 5: 
      digitalWrite(RGB1_R, LOW); digitalWrite(RGB1_G, LOW); digitalWrite(RGB1_B, LOW);
      digitalWrite(RGB2_R, LOW); digitalWrite(RGB2_G, LOW); digitalWrite(RGB2_B, LOW);
      digitalWrite(RGB3_R, LOW); digitalWrite(RGB3_G, HIGH); digitalWrite(RGB3_B, HIGH);
      break;
  }
}
void displayNumber(int number) {
  int tens = number / 10;
  int ones = number % 10;
  byte tensCode = segmentCodes[tens];
  byte onesCode = segmentCodes[ones];
  shiftOut(DS_PIN, SHCP_PIN, MSBFIRST, onesCode);
  shiftOut(DS_PIN, SHCP_PIN, MSBFIRST, tensCode);
  digitalWrite(STCP_PIN, HIGH);
  digitalWrite(STCP_PIN, LOW);
}
